window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[94]={"9400":{"example:9400:exzh":"He put new ideas into the project.","example:9400:exzh2":"She likes putting photos into albums.","example:9400:exzh3":"He's been pretty into horse racing lately.","example:9400:exzh4":"It's important to work this technology into the product.","example:9400:exzh5":"Don't forget to add the memo to the meeting."},"9401":{"example:9401:exzh":"The main body of that machine is made of metal.","example:9401:exzh2":"If the main body breaks, repairs are difficult.","example:9401:exzh3":"The main body of the app can be operated easily.","example:9401:exzh4":"With his proposal, the main body has to be considered carefully.","example:9401:exzh5":"The product's main unit and its accessories are sold separately."},"9402":{"example:9402:exzh":"The child pooped in the park.","example:9402:exzh2":"I was watching the dog poop.","example:9402:exzh3":"Tell me when you've pooped, okay?","example:9402:exzh4":"You go to the bathroom when you need to poop.","example:9402:exzh5":"He said he doesn't like poop.","grammar:9402:ex:trans":"The child pooped in the park.","grammar:9402:ex:structure":"子供は, 公園で＋うんちを＋した. 「で」 marks the place of the action, and 「うんちをする」 = poop. 「うんち」 = poop (baby talk).","grammar:9402:ex:explain":"The frame of this sentence is topic は + place で + noun を + する. 「子供は」 brings the child up as the topic with 「は」; the 「で」 in 「公園で」 marks where the action happens, which is different from 「に」 for a place of existence — if the sentence has an action, use 「で」. 「うんち」 is baby-talk for poop, and quite a few body-related words in Japanese have this reduplicated child-speech form. Adding 「をする」 turns the noun into an action, and the past tense of 「する」 is the irregular 「した」, so the sentence describes something that has already happened.","grammar:9402:ex:words:0:zh":"child","grammar:9402:ex:words:0:note":"こども","grammar:9402:ex:words:0:pos":"noun","grammar:9402:ex:words:1:zh":"(topic marker)","grammar:9402:ex:words:1:pos":"particle","grammar:9402:ex:words:2:zh":"park","grammar:9402:ex:words:2:note":"こうえん","grammar:9402:ex:words:2:pos":"noun","grammar:9402:ex:words:3:zh":"(place of the action)","grammar:9402:ex:words:3:pos":"particle","grammar:9402:ex:words:4:zh":"poop","grammar:9402:ex:words:4:note":"childish word","grammar:9402:ex:words:4:pos":"noun","grammar:9402:ex:words:5:zh":"(object marker)","grammar:9402:ex:words:5:pos":"particle","grammar:9402:ex:words:6:zh":"did","grammar:9402:ex:words:6:note":"うんちをする","grammar:9402:ex:words:6:pos":"verb","grammar:9402:ex:points:0":"うんち: poop (baby talk / colloquial)","grammar:9402:ex:points:1":"うんちをする: poop / で: place of action (公園で)","grammar:9402:ex2:trans":"I was watching the dog poop.","grammar:9402:ex2:structure":"〔犬がうんちをする＋の〕＋を＋見てた. 「〜のを見る」 = see … (doing something). 「見てた」 = 見ていた (casual).","grammar:9402:ex2:words:0:zh":"dog","grammar:9402:ex2:words:0:note":"いぬ","grammar:9402:ex2:words:0:pos":"noun","grammar:9402:ex2:words:1:zh":"(nominative)","grammar:9402:ex2:words:1:pos":"particle","grammar:9402:ex2:words:2:zh":"poop","grammar:9402:ex2:words:2:note":"childish word","grammar:9402:ex2:words:2:pos":"noun","grammar:9402:ex2:words:3:zh":"(object marker)","grammar:9402:ex2:words:3:pos":"particle","grammar:9402:ex2:words:4:zh":"do","grammar:9402:ex2:words:4:note":"dictionary form","grammar:9402:ex2:words:4:pos":"verb","grammar:9402:ex2:words:5:zh":"(nominalizer)","grammar:9402:ex2:words:5:pos":"particle","grammar:9402:ex2:words:6:zh":"(object marker)","grammar:9402:ex2:words:6:pos":"particle","grammar:9402:ex2:words:7:zh":"watching","grammar:9402:ex2:words:7:note":"〜ている casual speech","grammar:9402:ex2:words:7:pos":"verb","grammar:9402:ex2:points:0":"〜のを見る: see … (doing something)","grammar:9402:ex2:points:1":"〜てた: casual contraction of 〜ていた","grammar:9402:ex3:trans":"If you poop, tell me, okay?","grammar:9402:ex3:structure":"〔うんちが出たら〕, 教えてね. 「〜たら」 marks a condition, 「教えて」 = tell (me), and 「ね」 = a reminder tag.","grammar:9402:ex3:words:0:zh":"poop","grammar:9402:ex3:words:0:note":"childish word","grammar:9402:ex3:words:0:pos":"noun","grammar:9402:ex3:words:1:zh":"(nominative)","grammar:9402:ex3:words:1:pos":"particle","grammar:9402:ex3:words:2:zh":"if it comes out","grammar:9402:ex3:words:2:note":"ta-form＋ら (conditional)","grammar:9402:ex3:words:2:pos":"verb","grammar:9402:ex3:words:3:zh":"tell","grammar:9402:ex3:words:3:note":"te-form (request)","grammar:9402:ex3:words:3:pos":"verb","grammar:9402:ex3:words:4:zh":"(a reminder)","grammar:9402:ex3:words:4:pos":"particle","grammar:9402:ex3:points:0":"〜たら: if …, then (出たら = if it comes out)","grammar:9402:ex3:points:1":"教えてね: tell me, okay (a gentle reminder)","grammar:9402:ex4:trans":"When you go to the bathroom, it's when you want to poop.","grammar:9402:ex4:structure":"〔トイレに行くとき〕＋は, 〔うんちをしたい時〕. 「dictionary-form verb＋とき」 = when ….","grammar:9402:ex4:words:0:zh":"restroom","grammar:9402:ex4:words:0:note":"loanword","grammar:9402:ex4:words:0:pos":"noun","grammar:9402:ex4:words:1:zh":"(destination)","grammar:9402:ex4:words:1:pos":"particle","grammar:9402:ex4:words:2:zh":"go","grammar:9402:ex4:words:2:note":"dictionary form modification","grammar:9402:ex4:words:2:pos":"verb","grammar:9402:ex4:words:3:zh":"time","grammar:9402:ex4:words:3:note":"time","grammar:9402:ex4:words:3:pos":"noun","grammar:9402:ex4:words:4:zh":"(topic marker)","grammar:9402:ex4:words:4:pos":"particle","grammar:9402:ex4:words:5:zh":"poop","grammar:9402:ex4:words:5:note":"childish word","grammar:9402:ex4:words:5:pos":"noun","grammar:9402:ex4:words:6:zh":"(object marker)","grammar:9402:ex4:words:6:pos":"particle","grammar:9402:ex4:words:7:zh":"want to do","grammar:9402:ex4:words:7:note":"〜たい expresses desire","grammar:9402:ex4:words:7:pos":"verb","grammar:9402:ex4:words:8:zh":"time","grammar:9402:ex4:words:8:note":"とき","grammar:9402:ex4:words:8:pos":"noun","grammar:9402:ex4:points:0":"dictionary-form verb＋とき: when … (行くとき = when going)","grammar:9402:ex4:points:1":"うんちをしたい: want to poop","grammar:9402:ex5:trans":"He said he doesn't like poop.","grammar:9402:ex5:structure":"〜は＋〔うんちが嫌いだ〕＋と＋言っていた. 「〜と言っていた」 = was saying (that) ….","grammar:9402:ex5:words:0:zh":"he","grammar:9402:ex5:words:0:note":"かれ","grammar:9402:ex5:words:0:pos":"pronoun","grammar:9402:ex5:words:1:zh":"(topic marker)","grammar:9402:ex5:words:1:pos":"particle","grammar:9402:ex5:words:2:zh":"poop","grammar:9402:ex5:words:2:note":"childish word","grammar:9402:ex5:words:2:pos":"noun","grammar:9402:ex5:words:3:zh":"(object marker)","grammar:9402:ex5:words:3:pos":"particle","grammar:9402:ex5:words:4:zh":"unpleasant, annoying","grammar:9402:ex5:words:4:note":"きらい","grammar:9402:ex5:words:4:pos":"na-adjective","grammar:9402:ex5:words:5:zh":"(plain form)","grammar:9402:ex5:words:5:pos":"copula","grammar:9402:ex5:words:6:zh":"(quotation)","grammar:9402:ex5:words:6:pos":"particle","grammar:9402:ex5:words:7:zh":"tell","grammar:9402:ex5:words:7:note":"〜ている past","grammar:9402:ex5:words:7:pos":"verb","grammar:9402:ex5:points:0":"〜と言っていた: was saying that …","grammar:9402:ex5:points:1":"〜が嫌い: to dislike …"},"9403":{"example:9403:exzh":"He solved the problem in an orthodox way.","example:9403:exzh2":"I agree with the orthodox view.","example:9403:exzh3":"This field of study is based on orthodox theory.","example:9403:exzh4":"Understanding orthodox culture is important.","example:9403:exzh5":"He has an orthodox view of history."},"9404":{"example:9404:exzh":"Even past debts can be written off.","example:9404:exzh2":"That mistake will be written off.","example:9404:exzh3":"If these conditions are met, the contract is void.","example:9404:exzh4":"All the debts were written off.","example:9404:exzh5":"The promise with him was called off."},"9405":{"example:9405:exzh":"The clothes got soaking wet from the rain.","example:9405:exzh2":"He was playing in the water, soaking wet.","example:9405:exzh3":"After taking a shower, the hair is soaking wet.","example:9405:exzh4":"She went home with soaking wet shoes.","example:9405:exzh5":"Even if you wipe your body with a towel, it's still soaking wet."},"9407":{"example:9407:exzh":"There were options A and B, and I chose the latter.","example:9407:exzh2":"He supports the latter opinion rather than the former.","example:9407:exzh3":"In the latter case, it takes more time.","example:9407:exzh4":"This problem has a former and a latter.","example:9407:exzh5":"I think the latter is harder."},"9408":{"example:9408:exzh":"The bell is ringing.","example:9408:exzh2":"His voice rings through the room.","example:9408:exzh3":"The music is ringing out quietly.","example:9408:exzh4":"The alarm rang and woke me up.","example:9408:exzh5":"The sound of birds was echoing in the distance."},"9409":{"example:9409:exzh":"Nordic culture is unique.","example:9409:exzh2":"I want to travel in Northern Europe.","example:9409:exzh3":"The Nordic countries have beautiful nature.","example:9409:exzh4":"I like Norse mythology.","example:9409:exzh5":"Nordic food is delicious."},"9410":{"example:9410:exzh":"Buying it back is difficult.","example:9410:exzh2":"He bought that item back.","example:9410:exzh3":"You need money in order to buy it back.","example:9410:exzh4":"She intends to buy back the book she lost.","example:9410:exzh5":"He bought his own car back."},"9411":{"example:9411:exzh":"Paying taxes is important.","example:9411:exzh2":"He pays his taxes every year.","example:9411:exzh3":"You need to meet the payment deadline.","example:9411:exzh4":"I submitted the documents.","example:9411:exzh5":"Don't forget to pay the utility bills."},"9413":{"example:9413:exzh":"He sensed that something was wrong.","example:9413:exzh2":"She has sensed how I feel.","example:9413:exzh3":"My friend sensed the change in me.","example:9413:exzh4":"I sense that something special is going on.","example:9413:exzh5":"He sensed his own failure."},"9414":{"example:9414:exzh":"It's going to rain, so I'll take an umbrella.","example:9414:exzh2":"I bought a new umbrella. It's really cute.","example:9414:exzh3":"You need an umbrella on rainy days.","example:9414:exzh4":"She has an umbrella with a lovely design.","example:9414:exzh5":"Walking with an umbrella up is fun.","grammar:9414:ex:trans":"It's going to rain, so I'll take an umbrella with me.","grammar:9414:ex:structure":"雨が降るので、傘を持っていきます","grammar:9414:ex:explain":"「傘」 is a basic N5 noun and often appears with 「持つ」, 「さす」, and 「忘れる」. This sentence uses 「傘を持っていきます」 to say that an umbrella is being taken out with you. The 「雨が降るので」 at the front explains the reason, and the sentence is simple and natural.","grammar:9414:ex:words:0:zh":"rain","grammar:9414:ex:words:0:note":"あめ; rain","grammar:9414:ex:words:0:pos":"noun","grammar:9414:ex:words:1:zh":"subject marker","grammar:9414:ex:words:1:pos":"particle","grammar:9414:ex:words:2:zh":"down","grammar:9414:ex:words:2:note":"ふる: rain or snow falls","grammar:9414:ex:words:2:pos":"verb","grammar:9414:ex:words:3:zh":"because","grammar:9414:ex:words:3:pos":"particle","grammar:9414:ex:words:4:zh":"umbrella","grammar:9414:ex:words:4:note":"かさ: an umbrella used to keep off rain","grammar:9414:ex:words:4:pos":"noun","grammar:9414:ex:words:5:zh":"object marker","grammar:9414:ex:words:5:pos":"particle","grammar:9414:ex:words:6:zh":"carry, take","grammar:9414:ex:words:6:note":"もって; te-form","grammar:9414:ex:words:6:pos":"verb","grammar:9414:ex:words:7:zh":"go","grammar:9414:ex:words:7:pos":"auxiliary verb","grammar:9414:ex:points:0":"「傘」 is read 「かさ」 and means an umbrella used when it rains.","grammar:9414:ex:points:1":"「雨が降るので」 uses 「ので」 to give the reason for taking an umbrella.","grammar:9414:ex:points:2":"「持っていきます」 means taking something to another place.","grammar:9414:ex2:trans":"I bought a new umbrella, and it's really cute.","grammar:9414:ex2:structure":"〜は＋〔新しい傘〕＋を＋買いました。それは＋とても＋かわいいです。","grammar:9414:ex2:words:0:zh":"I","grammar:9414:ex2:words:0:note":"わたし","grammar:9414:ex2:words:0:pos":"pronoun","grammar:9414:ex2:words:1:zh":"(topic marker)","grammar:9414:ex2:words:1:pos":"particle","grammar:9414:ex2:words:2:zh":"new","grammar:9414:ex2:words:2:note":"あたらしい","grammar:9414:ex2:words:2:pos":"adjective","grammar:9414:ex2:words:3:zh":"umbrella","grammar:9414:ex2:words:3:note":"かさ","grammar:9414:ex2:words:3:pos":"noun","grammar:9414:ex2:words:4:zh":"(object marker)","grammar:9414:ex2:words:4:pos":"particle","grammar:9414:ex2:words:5:zh":"bought","grammar:9414:ex2:words:5:note":"かいました","grammar:9414:ex2:words:5:pos":"verb","grammar:9414:ex2:words:6:zh":"that","grammar:9414:ex2:words:6:pos":"pronoun","grammar:9414:ex2:words:7:zh":"(topic marker)","grammar:9414:ex2:words:7:pos":"particle","grammar:9414:ex2:words:8:zh":"extremely","grammar:9414:ex2:words:8:pos":"adverb","grammar:9414:ex2:words:9:zh":"cute","grammar:9414:ex2:words:9:pos":"adjective","grammar:9414:ex2:words:10:zh":"(polite form)","grammar:9414:ex2:words:10:pos":"copula","grammar:9414:ex2:points:0":"新しい傘: a new umbrella","grammar:9414:ex2:points:1":"それは〜です: that is …","grammar:9414:ex3:trans":"You need an umbrella on rainy days.","grammar:9414:ex3:structure":"〔雨の日〕＋は, 傘が＋必要です. 「雨の日」 = a rainy day.","grammar:9414:ex3:words:0:zh":"rain","grammar:9414:ex3:words:0:note":"あめ","grammar:9414:ex3:words:0:pos":"noun","grammar:9414:ex3:words:1:zh":"'s","grammar:9414:ex3:words:1:pos":"particle","grammar:9414:ex3:words:2:zh":"day","grammar:9414:ex3:words:2:note":"ひ","grammar:9414:ex3:words:2:pos":"noun","grammar:9414:ex3:words:3:zh":"(topic marker)","grammar:9414:ex3:words:3:pos":"particle","grammar:9414:ex3:words:4:zh":"umbrella","grammar:9414:ex3:words:4:note":"かさ","grammar:9414:ex3:words:4:pos":"noun","grammar:9414:ex3:words:5:zh":"(nominative)","grammar:9414:ex3:words:5:pos":"particle","grammar:9414:ex3:words:6:zh":"necessary","grammar:9414:ex3:words:6:note":"ひつよう","grammar:9414:ex3:words:6:pos":"na-adjective","grammar:9414:ex3:words:7:zh":"(polite form)","grammar:9414:ex3:words:7:pos":"copula","grammar:9414:ex3:points:0":"雨の日: a rainy day","grammar:9414:ex3:points:1":"〜が必要: to need…","grammar:9414:ex4:trans":"She has an umbrella with a lovely design.","grammar:9414:ex4:structure":"〜は＋〔素敵なデザインの傘〕＋を＋持っています. 「素敵な」 modifies with な.","grammar:9414:ex4:words:0:zh":"she","grammar:9414:ex4:words:0:note":"かのじょ","grammar:9414:ex4:words:0:pos":"pronoun","grammar:9414:ex4:words:1:zh":"(topic marker)","grammar:9414:ex4:words:1:pos":"particle","grammar:9414:ex4:words:2:zh":"lovely","grammar:9414:ex4:words:2:note":"すてき","grammar:9414:ex4:words:2:pos":"na-adjective","grammar:9414:ex4:words:3:zh":"design","grammar:9414:ex4:words:3:note":"loanword","grammar:9414:ex4:words:3:pos":"noun","grammar:9414:ex4:words:4:zh":"'s","grammar:9414:ex4:words:4:pos":"particle","grammar:9414:ex4:words:5:zh":"umbrella","grammar:9414:ex4:words:5:note":"かさ","grammar:9414:ex4:words:5:pos":"noun","grammar:9414:ex4:words:6:zh":"(object marker)","grammar:9414:ex4:words:6:pos":"particle","grammar:9414:ex4:words:7:zh":"own, have","grammar:9414:ex4:words:7:note":"〜ている expresses a state","grammar:9414:ex4:words:7:pos":"verb","grammar:9414:ex4:points:0":"素敵なデザインの傘: an umbrella with a lovely design","grammar:9414:ex4:points:1":"〜を持っている: to have…","grammar:9414:ex5:trans":"Walking with an umbrella up is fun.","grammar:9414:ex5:structure":"〔傘をさして歩く＋の〕＋は＋楽しいです. 「傘をさす」 = hold up an umbrella, and 「さして」 links with the te-form.","grammar:9414:ex5:words:0:zh":"umbrella","grammar:9414:ex5:words:0:note":"かさ","grammar:9414:ex5:words:0:pos":"noun","grammar:9414:ex5:words:1:zh":"(object marker)","grammar:9414:ex5:words:1:pos":"particle","grammar:9414:ex5:words:2:zh":"hold up (and)","grammar:9414:ex5:words:2:note":"te-form","grammar:9414:ex5:words:2:pos":"verb","grammar:9414:ex5:words:3:zh":"walking","grammar:9414:ex5:words:3:note":"dictionary form","grammar:9414:ex5:words:3:pos":"verb","grammar:9414:ex5:words:4:zh":"(nominalizer)","grammar:9414:ex5:words:4:pos":"particle","grammar:9414:ex5:words:5:zh":"(topic marker)","grammar:9414:ex5:words:5:pos":"particle","grammar:9414:ex5:words:6:zh":"enjoyable","grammar:9414:ex5:words:6:note":"たのしい","grammar:9414:ex5:words:6:pos":"adjective","grammar:9414:ex5:words:7:zh":"(polite form)","grammar:9414:ex5:words:7:pos":"copula","grammar:9414:ex5:points:0":"傘をさす: hold up an umbrella","grammar:9414:ex5:points:1":"verb＋の＋は楽しい: doing … is fun","exam:9414:zh":"So that my body wouldn't get wet in the rain, I opened an umbrella over my head.","exam:9414:why":"「傘を開く」 means to open an umbrella. You do put a 「帽子」 on your head, but 「開く」 can't be used for putting on a hat."},"9416":{"example:9416:exzh":"He asked a direct question.","example:9416:exzh2":"I'll say it straight: your opinion is wrong.","example:9416:exzh3":"This problem must be tackled head-on.","example:9416:exzh4":"To get straight to the point, what do you need?","example:9416:exzh5":"It's important to think about things head-on."},"9417":{"example:9417:exzh":"Metal corrodes easily.","example:9417:exzh2":"Paint is used to prevent corrosion.","example:9417:exzh3":"This material is resistant to corrosion.","example:9417:exzh4":"I found that the corrosion is getting worse.","example:9417:exzh5":"Corrosion progresses over time."},"9418":{"example:9418:exzh":"Memorizing this word is tough.","example:9418:exzh2":"He's good at memorizing kanji.","example:9418:exzh3":"I memorized a lot of things for the exam.","example:9418:exzh4":"Memorization has been my weak point for a long time.","example:9418:exzh5":"Memorizing with this method is easy."},"9419":{"example:9419:exzh":"The expanse of this region is wonderful.","example:9419:exzh2":"The reach of her influence is great.","example:9419:exzh3":"We need a project with breadth.","example:9419:exzh4":"The way that idea spreads is interesting.","example:9419:exzh5":"To prevent the spread of infection, wash your hands well."},"9420":{"example:9420:exzh":"He got straight to the point.","example:9420:exzh2":"We need an opinion that cuts straight to the point.","example:9420:exzh3":"A direct approach is the most effective.","example:9420:exzh4":"You should answer questions directly.","example:9420:exzh5":"Let's narrow down the target with a direct approach."},"9421":{"example:9421:exzh":"Don't forget to lock up, because the house is safe.","example:9421:exzh2":"Please check that the lock is secure.","example:9421:exzh3":"Please tell me how to lock the door.","example:9421:exzh4":"Locking up at night gives you peace of mind.","example:9421:exzh5":"If you don't lock up, a thief might get in."},"9422":{"example:9422:exzh":"It's a shame that the memories are fading.","example:9422:exzh2":"As time passed, the color faded.","example:9422:exzh3":"That feeling is gradually fading.","example:9422:exzh4":"I want to get back the memories that have faded.","example:9422:exzh5":"If your joy starts to fade, try starting something new."},"9424":{"example:9424:exzh":"This technology was developed to strengthen communications.","example:9424:exzh2":"He exercises every day to build up his strength.","example:9424:exzh3":"The government announced a new policy to strengthen the economy.","example:9424:exzh4":"This training is said to build muscle.","example:9424:exzh5":"Enhanced learning is an effective way to learn."},"9425":{"example:9425:exzh":"This river has a gentle flow.","example:9425:exzh2":"He is a peace-loving person.","example:9425:exzh3":"I like walking on flat roads.","example:9425:exzh4":"It's safe to play in a flat area.","example:9425:exzh5":"This area is flat and quiet."},"9426":{"example:9426:exzh":"In any case, we have to move forward.","example:9426:exzh2":"In any case, whatever the result, that's what matters.","example:9426:exzh3":"In any case, let's think about the next step.","example:9426:exzh4":"In any case, I respect your opinion.","example:9426:exzh5":"In any case, we need to move the plan forward."},"9427":{"example:9427:exzh":"Working from home is becoming more common.","example:9427:exzh2":"He works from home.","example:9427:exzh3":"I enjoy life at home.","example:9427:exzh4":"Studying at home is popular too.","example:9427:exzh5":"While I was at home, I got hooked on cooking."},"9429":{"example:9429:exzh":"Bulgaria is a beautiful country.","example:9429:exzh2":"I'm interested in Bulgarian culture.","example:9429:exzh3":"Have you ever eaten Bulgarian food?","example:9429:exzh4":"I want to travel to Bulgaria.","example:9429:exzh5":"Bulgarian wine is very famous."},"9430":{"example:9430:exzh":"The activity is suspended.","example:9430:exzh2":"He made the decision to suspend it.","example:9430:exzh3":"Please tell me the reason for the suspension.","example:9430:exzh4":"That project is currently on hold.","example:9430:exzh5":"It restarted after a one-year pause."},"9432":{"example:9432:exzh":"The fruit needs to be sorted.","example:9432:exzh2":"I'll sort out the fresh ones.","example:9432:exzh3":"Sorting is important to maintain quality.","example:9432:exzh4":"He sorts things carefully.","example:9432:exzh5":"There are times when you need to sort out your work."},"9434":{"example:9434:exzh":"His catchphrase is funny.","example:9434:exzh2":"Catchphrases come out naturally.","example:9434:exzh3":"I'll never forget my mother's catchphrase.","example:9434:exzh4":"I like her catchphrase.","example:9434:exzh5":"I want to break my habit of saying that catchphrase."},"9435":{"example:9435:exzh":"He has a hearty appetite.","example:9435:exzh2":"Children have a lot of curiosity.","example:9435:exzh3":"It's a period of vigorous growth.","example:9435:exzh4":"The plants are growing vigorously.","example:9435:exzh5":"She has abundant energy."},"9436":{"example:9436:exzh":"Tennessee has a lot of charm.","example:9436:exzh2":"I traveled to Tennessee.","example:9436:exzh3":"Tennessee is famous for its music.","example:9436:exzh4":"The scenery in Tennessee is beautiful.","example:9436:exzh5":"A friend of mine lives in Tennessee."},"9437":{"example:9437:exzh":"He is one of the government's cabinet ministers.","example:9437:exzh2":"The cabinet ministers held a meeting.","example:9437:exzh3":"A new cabinet minister was appointed.","example:9437:exzh4":"Cabinet ministers make important decisions.","example:9437:exzh5":"She works as a cabinet minister."},"9438":{"example:9438:exzh":"We had a picnic outdoors.","example:9438:exzh2":"The weather is nice, so let's exercise outdoors.","example:9438:exzh3":"I like outdoor activities.","example:9438:exzh4":"Playing outside is fun.","example:9438:exzh5":"He does outdoor work."},"9439":{"example:9439:exzh":"I got my clothes wet in the rain.","example:9439:exzh2":"Be careful not to get your hands wet.","example:9439:exzh3":"Wet the plants with water.","example:9439:exzh4":"I wet my face with a towel.","example:9439:exzh5":"In his hurry, he got his shoes wet."},"9441":{"example:9441:exzh":"He trampled on my dream.","example:9441:exzh2":"That kind of behavior tramples on other people's rights.","example:9441:exzh3":"The flowers in the flowerbed had been trampled by someone.","example:9441:exzh4":"Trampling on the law is not allowed.","example:9441:exzh5":"We must not trample on others."},"9442":{"example:9442:exzh":"He shot down an enemy plane.","example:9442:exzh2":"The soldier shot down an enemy drone.","example:9442:exzh3":"This device can shoot down small aircraft.","example:9442:exzh4":"You should learn techniques that can shoot things down.","example:9442:exzh5":"His aim was perfect, and he shot down everything."},"9443":{"example:9443:exzh":"Government bonds are one way for a country to raise funds.","example:9443:exzh2":"Japanese government bonds are stable.","example:9443:exzh3":"Many countries issue government bonds.","example:9443:exzh4":"Government bonds often have low interest rates.","example:9443:exzh5":"He decided to invest in government bonds."},"9444":{"example:9444:exzh":"This movie is a great comedy.","example:9444:exzh2":"He works as a comedian.","example:9444:exzh3":"I'm watching a comedy and laughing.","example:9444:exzh4":"This comedy is suitable for the whole family.","example:9444:exzh5":"Comedy helps relieve stress."},"9445":{"example:9445:exzh":"Take a bath every night to relax.","example:9445:exzh2":"Bathing in a hot spring is the best.","example:9445:exzh3":"It's important to wash your body before getting in the bath.","example:9445:exzh4":"He feels refreshed after a bath.","example:9445:exzh5":"Bath time is my time to relax."},"9446":{"example:9446:exzh":"I bought a guidebook before my trip.","example:9446:exzh2":"This guidebook has a lot of information.","example:9446:exzh3":"He went sightseeing with a guidebook.","example:9446:exzh4":"I found a recommended restaurant in the guidebook.","example:9446:exzh5":"The guidebook for this area is very helpful."},"9447":{"example:9447:exzh":"「八百」 means 800.","example:9447:exzh2":"I live in the house at lot number 800.","example:9447:exzh3":"I have 800 books.","example:9447:exzh4":"He ran 800 meters.","example:9447:exzh5":"I saw a product for 800 at the store.","grammar:9447:ex:trans":"八百 means 800.","grammar:9447:ex:structure":"八百は、800を＋意味します。「〜を意味する」 = to mean … 「八百」 = 八百 (800).","grammar:9447:ex:explain":"「〜を意味する」 is a fixed expression for explaining what a word means — \"means\" or \"refers to.\" The thing being explained is marked with 「を」, and it appears often in explanatory and definitional writing. The Japanese number 「八百」 is read 「はっぴゃく」; note that 「百」 changes to a geminated or semi-voiced sound after three, six and eight (さんびゃく、ろっぴゃく、はっぴゃく), which is a fixed rule for reading numbers.","grammar:9447:ex:words:0:zh":"eight hundred","grammar:9447:ex:words:0:note":"はっぴゃく","grammar:9447:ex:words:0:pos":"noun","grammar:9447:ex:words:1:zh":"(topic marker)","grammar:9447:ex:words:1:pos":"particle","grammar:9447:ex:words:2:zh":"eight hundred","grammar:9447:ex:words:2:note":"はっぴゃく","grammar:9447:ex:words:2:pos":"noun","grammar:9447:ex:words:3:zh":"(object marker)","grammar:9447:ex:words:3:pos":"particle","grammar:9447:ex:words:4:zh":"means","grammar:9447:ex:words:4:note":"いみします","grammar:9447:ex:words:4:pos":"verb","grammar:9447:ex:points:0":"八百（はっぴゃく）: eight hundred, 800","grammar:9447:ex:points:1":"〜を意味する: mean, refer to …","grammar:9447:ex2:trans":"I live in the house at number 800.","grammar:9447:ex2:structure":"〜番地の家に住んでいます","grammar:9447:ex2:explain":"「八百番地」 is plot number 800 in an address, and 「の」 makes that address modify 「家」. The te-form of 「住む」 is 「住んで」, so the polite ongoing-state form is 「住んでいます」. Here it describes your current living situation, not a move that is in progress.","grammar:9447:ex2:words:0:zh":"eight hundred","grammar:9447:ex2:words:0:note":"はっぴゃく","grammar:9447:ex2:words:0:pos":"numeral","grammar:9447:ex2:words:1:zh":"plot number, the number in an address","grammar:9447:ex2:words:1:note":"ばんち","grammar:9447:ex2:words:1:pos":"noun","grammar:9447:ex2:words:2:zh":"(links nouns, marking the address relationship)","grammar:9447:ex2:words:2:pos":"particle","grammar:9447:ex2:words:3:zh":"house","grammar:9447:ex2:words:3:note":"いえ","grammar:9447:ex2:words:3:pos":"noun","grammar:9447:ex2:words:4:zh":"(the place of residence)","grammar:9447:ex2:words:4:pos":"particle","grammar:9447:ex2:words:5:zh":"living","grammar:9447:ex2:words:5:note":"すん","grammar:9447:ex2:words:5:pos":"verb","grammar:9447:ex2:words:6:zh":"(links a continuing-state expression)","grammar:9447:ex2:words:6:pos":"particle","grammar:9447:ex2:words:7:zh":"(continuing to be in a state of living there)","grammar:9447:ex2:words:7:pos":"verb","grammar:9447:ex2:words:8:zh":"(polite ending)","grammar:9447:ex2:words:8:pos":"auxiliary verb","grammar:9447:ex2:points:0":"「八百」 is read 「はっぴゃく」, not simply 「はち」 and 「ひゃく」 joined together.","grammar:9447:ex2:points:1":"「場所に住んでいます」 says you currently live somewhere, with the place marked by 「に」.","grammar:9447:ex3:trans":"I own eight hundred books.","grammar:9447:ex3:structure":"〜は＋〔八百の本〕＋を＋持っています。「八百の本」 = eight hundred books.","grammar:9447:ex3:words:0:zh":"I","grammar:9447:ex3:words:0:note":"わたし","grammar:9447:ex3:words:0:pos":"pronoun","grammar:9447:ex3:words:1:zh":"(topic marker)","grammar:9447:ex3:words:1:pos":"particle","grammar:9447:ex3:words:2:zh":"eight hundred","grammar:9447:ex3:words:2:note":"はっぴゃく","grammar:9447:ex3:words:2:pos":"noun","grammar:9447:ex3:words:3:zh":"'s","grammar:9447:ex3:words:3:pos":"particle","grammar:9447:ex3:words:4:zh":"book","grammar:9447:ex3:words:4:note":"ほん","grammar:9447:ex3:words:4:pos":"noun","grammar:9447:ex3:words:5:zh":"(object marker)","grammar:9447:ex3:words:5:pos":"particle","grammar:9447:ex3:words:6:zh":"own, have","grammar:9447:ex3:words:6:note":"〜ている expresses a state","grammar:9447:ex3:words:6:pos":"verb","grammar:9447:ex3:points:0":"八百の本: eight hundred books","grammar:9447:ex3:points:1":"〜を持っている: to have…","grammar:9447:ex4:trans":"He ran eight hundred meters.","grammar:9447:ex4:structure":"〜は＋八百メートル＋走りました。「八百メートル」 = eight hundred meters.","grammar:9447:ex4:words:0:zh":"he","grammar:9447:ex4:words:0:note":"かれ","grammar:9447:ex4:words:0:pos":"pronoun","grammar:9447:ex4:words:1:zh":"(topic marker)","grammar:9447:ex4:words:1:pos":"particle","grammar:9447:ex4:words:2:zh":"eight hundred meters","grammar:9447:ex4:words:2:note":"はっぴゃくメートル","grammar:9447:ex4:words:2:pos":"noun","grammar:9447:ex4:words:3:zh":"ran","grammar:9447:ex4:words:3:note":"はしりました","grammar:9447:ex4:words:3:pos":"verb","grammar:9447:ex4:points:0":"八百メートル: eight hundred meters","grammar:9447:ex4:points:1":"走る: to run","grammar:9447:ex5:trans":"I saw some 八百 products at the store.","grammar:9447:ex5:structure":"商店で、〔八百の商品〕＋を＋見かけました。「で」 marks where the action takes place, and 「見かける」 = to catch sight of (by chance).","grammar:9447:ex5:words:0:zh":"shop","grammar:9447:ex5:words:0:note":"しょうてん","grammar:9447:ex5:words:0:pos":"noun","grammar:9447:ex5:words:1:zh":"(place of the action)","grammar:9447:ex5:words:1:pos":"particle","grammar:9447:ex5:words:2:zh":"eight hundred","grammar:9447:ex5:words:2:note":"はっぴゃく","grammar:9447:ex5:words:2:pos":"noun","grammar:9447:ex5:words:3:zh":"'s","grammar:9447:ex5:words:3:pos":"particle","grammar:9447:ex5:words:4:zh":"product","grammar:9447:ex5:words:4:note":"しょうひん","grammar:9447:ex5:words:4:pos":"noun","grammar:9447:ex5:words:5:zh":"(object marker)","grammar:9447:ex5:words:5:pos":"particle","grammar:9447:ex5:words:6:zh":"saw","grammar:9447:ex5:words:6:note":"みかけました","grammar:9447:ex5:words:6:pos":"verb","grammar:9447:ex5:points:0":"見かける: catch sight of (by chance)","grammar:9447:ex5:points:1":"八百の商品: 八百 products"},"9448":{"example:9448:exzh":"Negligence at work is unacceptable.","example:9448:exzh2":"A negligent attitude is a problem.","example:9448:exzh3":"He lost his job because of his negligence.","example:9448:exzh4":"His negligence made the results turn out badly.","example:9448:exzh5":"We make plans so we don't get careless."},"9450":{"example:9450:exzh":"Formal procedures are required.","example:9450:exzh2":"Have you had a formal education?","example:9450:exzh3":"Please refer to official materials.","example:9450:exzh4":"It's important to learn through formal methods.","example:9450:exzh5":"He took the official exam."},"9451":{"example:9451:exzh":"The new movie will be shown this month.","example:9451:exzh2":"They plan to stage a play next week.","example:9451:exzh3":"After it was staged, it became a hot topic.","example:9451:exzh4":"Many plays will be performed at this school festival.","example:9451:exzh5":"She's looking forward to the performance of the new piece."},"9452":{"example:9452:exzh":"A low-temperature advisory has been issued.","example:9452:exzh2":"Because of the low temperature, it's better not to go outside.","example:9452:exzh3":"Food can spoil at low temperatures.","example:9452:exzh4":"You need warm clothes when the temperature is low.","example:9452:exzh5":"They say the temperature is low today."},"9453":{"example:9453:exzh":"He has been through many setbacks.","example:9453:exzh2":"It's important to overcome setbacks.","example:9453:exzh3":"Even if you hit a setback, please don't give up.","example:9453:exzh4":"That setback made him stronger.","example:9453:exzh5":"You grow by going through setbacks."},"9455":{"example:9455:exzh":"His house is a crumbling old place.","example:9455:exzh2":"That car is a wreck, so it won't run.","example:9455:exzh3":"It's a wreck, but it's full of memories.","example:9455:exzh4":"I got rid of the beat-up old furniture.","example:9455:exzh5":"Walking on a broken-up road is tough."},"9456":{"example:9456:exzh":"My hair got all tangled.","example:9456:exzh2":"It took a long time to untangle it.","example:9456:exzh3":"The tangled cord is in the way.","example:9456:exzh4":"He did a craft project with tangled thread.","example:9456:exzh5":"There was a tangle, so I started over."},"9457":{"example:9457:exzh":"He answered with such an attitude.","example:9457:exzh2":"Such facts came to light.","example:9457:exzh3":"She has such a smile.","example:9457:exzh4":"We reached such a conclusion.","example:9457:exzh5":"It's hard to deal with such a situation."},"9458":{"example:9458:exzh":"He showed off his own success.","example:9458:exzh2":"It's better to hold back from showing off.","example:9458:exzh3":"Showing off gets you nothing.","example:9458:exzh4":"That showing off left him isolated.","example:9458:exzh5":"There's no reason to show off."},"9459":{"example:9459:exzh":"There's a big marsh in this area.","example:9459:exzh2":"The marsh's ecosystem is very unique.","example:9459:exzh3":"He likes exploring the marsh.","example:9459:exzh4":"Marsh tourism has become a new industry.","example:9459:exzh5":"The marsh is a habitat for many plants and animals."},"9461":{"example:9461:exzh":"I wear sandals in summer.","example:9461:exzh2":"These sandals are very comfortable.","example:9461:exzh3":"Sandals are perfect for a trip to the beach.","example:9461:exzh4":"I bought sandals for my child.","example:9461:exzh5":"Don't forget to take off your sandals.","grammar:9461:ex:trans":"In summer, I wear sandals.","grammar:9461:ex:structure":"夏＋には、サンダルを＋履きます。「〜には」 emphasizes the time, 「〜を履く」 = to wear (shoes). 「サンダル」 = sandals.","grammar:9461:ex:explain":"「〜を履く」 is the verb used specifically for shoes, socks, trousers and other things worn on the lower body; for the upper body you use 「着る」, and for hats 「かぶる」. Japanese switches its \"wear\" verb depending on the body part, so it's best to memorize them as a set. 「夏には」 is a time noun plus 「に」 with 「は」 stacked on top, bringing out a contrastive, habitual tone of \"whenever summer comes…\"; the polite present tense at the end expresses a repeated habit.","grammar:9461:ex:words:0:zh":"summer","grammar:9461:ex:words:0:note":"なつ","grammar:9461:ex:words:0:pos":"noun","grammar:9461:ex:words:1:zh":"(time + emphasis)","grammar:9461:ex:words:1:pos":"particle","grammar:9461:ex:words:2:zh":"sandals","grammar:9461:ex:words:2:note":"loanword from English: sandal","grammar:9461:ex:words:2:pos":"noun","grammar:9461:ex:words:3:zh":"(object marker)","grammar:9461:ex:words:3:pos":"particle","grammar:9461:ex:words:4:zh":"wear","grammar:9461:ex:words:4:note":"はきます","grammar:9461:ex:words:4:pos":"verb","grammar:9461:ex:points:0":"サンダル: sandals","grammar:9461:ex:points:1":"〜を履く: wear (shoes, trousers)／〜には: in … (夏には = in summer)","grammar:9461:ex2:trans":"These sandals are very comfortable.","grammar:9461:ex2:structure":"この＋noun＋は＋とても＋快適です。","grammar:9461:ex2:words:0:zh":"this","grammar:9461:ex2:words:0:pos":"pre-noun adjectival","grammar:9461:ex2:words:1:zh":"sandals","grammar:9461:ex2:words:1:note":"loanword","grammar:9461:ex2:words:1:pos":"noun","grammar:9461:ex2:words:2:zh":"(topic marker)","grammar:9461:ex2:words:2:pos":"particle","grammar:9461:ex2:words:3:zh":"extremely","grammar:9461:ex2:words:3:pos":"adverb","grammar:9461:ex2:words:4:zh":"comfortable","grammar:9461:ex2:words:4:note":"かいてき","grammar:9461:ex2:words:4:pos":"na-adjective","grammar:9461:ex2:words:5:zh":"(polite form)","grammar:9461:ex2:words:5:pos":"copula","grammar:9461:ex2:points:0":"快適: comfortable","grammar:9461:ex2:points:1":"このサンダル: these sandals","grammar:9461:ex3:trans":"Sandals are the best choice for a trip to the beach.","grammar:9461:ex3:structure":"サンダルは、〔海に行くとき〕＋に、最適だ。「〜に最適」 = perfect for …，「行くとき」 = when you go.","grammar:9461:ex3:words:0:zh":"sandals","grammar:9461:ex3:words:0:note":"loanword","grammar:9461:ex3:words:0:pos":"noun","grammar:9461:ex3:words:1:zh":"(topic marker)","grammar:9461:ex3:words:1:pos":"particle","grammar:9461:ex3:words:2:zh":"sea","grammar:9461:ex3:words:2:note":"うみ","grammar:9461:ex3:words:2:pos":"noun","grammar:9461:ex3:words:3:zh":"(destination)","grammar:9461:ex3:words:3:pos":"particle","grammar:9461:ex3:words:4:zh":"go","grammar:9461:ex3:words:4:note":"dictionary form modification","grammar:9461:ex3:words:4:pos":"verb","grammar:9461:ex3:words:5:zh":"time","grammar:9461:ex3:words:5:note":"time","grammar:9461:ex3:words:5:pos":"noun","grammar:9461:ex3:words:6:zh":"(point in time)","grammar:9461:ex3:words:6:pos":"particle","grammar:9461:ex3:words:7:zh":"best suited for","grammar:9461:ex3:words:7:note":"さいてき","grammar:9461:ex3:words:7:pos":"na-adjective","grammar:9461:ex3:words:8:zh":"(plain form)","grammar:9461:ex3:words:8:pos":"copula","grammar:9461:ex3:points:0":"〜に最適: perfect for …","grammar:9461:ex3:points:1":"verb dictionary form＋とき: when … (海に行くとき = when you go to the beach)","grammar:9461:ex4:trans":"I bought sandals for the kids.","grammar:9461:ex4:structure":"〔子供のために〕、サンダルを＋買った。「〜のために」 = for the sake of …","grammar:9461:ex4:words:0:zh":"child","grammar:9461:ex4:words:0:note":"こども","grammar:9461:ex4:words:0:pos":"noun","grammar:9461:ex4:words:1:zh":"'s","grammar:9461:ex4:words:1:pos":"particle","grammar:9461:ex4:words:2:zh":"for the sake of","grammar:9461:ex4:words:2:note":"purpose","grammar:9461:ex4:words:2:pos":"noun","grammar:9461:ex4:words:3:zh":"(purpose)","grammar:9461:ex4:words:3:pos":"particle","grammar:9461:ex4:words:4:zh":"sandals","grammar:9461:ex4:words:4:note":"loanword","grammar:9461:ex4:words:4:pos":"noun","grammar:9461:ex4:words:5:zh":"(object marker)","grammar:9461:ex4:words:5:pos":"particle","grammar:9461:ex4:words:6:zh":"bought","grammar:9461:ex4:words:6:note":"かった","grammar:9461:ex4:words:6:pos":"verb","grammar:9461:ex4:points:0":"〜のために: for … (子供のために = for the kids)","grammar:9461:ex4:points:1":"サンダルを買う: buy sandals","grammar:9461:ex5:trans":"Don't forget to take off your sandals.","grammar:9461:ex5:structure":"〔サンダルを脱ぐ＋の〕＋を＋忘れないで。「〜のを忘れないで」 = don't forget to … 「サンダルを脱ぐ」 = take off sandals.","grammar:9461:ex5:words:0:zh":"sandals","grammar:9461:ex5:words:0:note":"loanword","grammar:9461:ex5:words:0:pos":"noun","grammar:9461:ex5:words:1:zh":"(object marker)","grammar:9461:ex5:words:1:pos":"particle","grammar:9461:ex5:words:2:zh":"to take off","grammar:9461:ex5:words:2:note":"ぬぐ; dictionary form","grammar:9461:ex5:words:2:pos":"verb","grammar:9461:ex5:words:3:zh":"(nominalizer)","grammar:9461:ex5:words:3:pos":"particle","grammar:9461:ex5:words:4:zh":"(object marker)","grammar:9461:ex5:words:4:pos":"particle","grammar:9461:ex5:words:5:zh":"don't forget","grammar:9461:ex5:words:5:note":"〜ないで","grammar:9461:ex5:words:5:pos":"verb","grammar:9461:ex5:points:0":"〜のを忘れないで: don't forget to …","grammar:9461:ex5:points:1":"サンダルを脱ぐ: take off sandals"},"9463":{"example:9463:exzh":"He took his son along to the park.","example:9463:exzh2":"I went traveling with my friends in tow.","example:9463:exzh3":"I take the dog along for a walk.","example:9463:exzh4":"She took her little sister along shopping.","example:9463:exzh5":"He took his grandfather along to the hospital."},"9464":{"example:9464:exzh":"I have a morning set every morning.","example:9464:exzh2":"The breakfast menu is very extensive.","example:9464:exzh3":"The breakfast at this café is delicious.","example:9464:exzh4":"Making breakfast is fun.","example:9464:exzh5":"He read the newspaper while eating his breakfast set."},"9465":{"example:9465:exzh":"This cake is super delicious!","example:9465:exzh2":"I'm super tired today.","example:9465:exzh3":"That movie was super interesting.","example:9465:exzh4":"She's super kind.","example:9465:exzh5":"I've been super busy lately."},"9466":{"example:9466:exzh":"Mishima has beautiful nature.","example:9466:exzh2":"He's from Mishima.","example:9466:exzh3":"I joined the festival in Mishima.","example:9466:exzh4":"Mishima is famous as a tourist destination.","example:9466:exzh5":"I have a friend living in Mishima."},"9468":{"example:9468:exzh":"A party was held to celebrate the promotion.","example:9468:exzh2":"She received congratulations on her marriage.","example:9468:exzh3":"I wrote a congratulatory letter.","example:9468:exzh4":"I congratulate my friend on their success.","example:9468:exzh5":"I'll send you some words of congratulations."},"9469":{"example:9469:exzh":"Pufferfish is one of Japanese dishes.","example:9469:exzh2":"Eating pufferfish is dangerous.","example:9469:exzh3":"I like pufferfish sashimi.","example:9469:exzh4":"I want to eat pufferfish dishes.","example:9469:exzh5":"Pufferfish season has arrived."},"9470":{"example:9470:exzh":"A coconut is a sweet fruit.","example:9470:exzh2":"I like coconut juice.","example:9470:exzh3":"I like the scent of coconut.","example:9470:exzh4":"A coconut shell is hard.","example:9470:exzh5":"Coconut trees are common in tropical countries."},"9471":{"example:9471:exzh":"He is known as an insider.","example:9471:exzh2":"Insider trading is illegal.","example:9471:exzh3":"Getting insider information is difficult.","example:9471:exzh4":"There's a risk that comes from insiders.","example:9471:exzh5":"This is a case that an insider exposed."},"9472":{"example:9472:exzh":"Please develop this film.","example:9472:exzh2":"How long does developing take?","example:9472:exzh3":"He is very good at developing film.","example:9472:exzh4":"Please tell me a place where I can get film developed.","example:9472:exzh5":"You can even develop photos with a digital camera."},"9473":{"example:9473:exzh":"He's quitting the company? That's the first I've heard of it.","example:9473:exzh2":"That's the first I've heard of that news.","example:9473:exzh3":"Her stories are always news to me.","example:9473:exzh4":"Thanks for telling me — that's the first I've heard of it."},"9474":{"example:9474:exzh":"He attends medical school.","example:9474:exzh2":"The entrance exam for medical school is hard.","example:9474:exzh3":"I'm studying hard to get into medical school.","example:9474:exzh4":"She graduated from medical school.","example:9474:exzh5":"Life as a medical student is busy."},"9475":{"example:9475:exzh":"Let's push the new feature hard.","example:9475:exzh2":"He uses push notifications.","example:9475:exzh3":"We have to push the new feature.","example:9475:exzh4":"Pushing is important.","example:9475:exzh5":"The timing of the push is important."},"9476":{"example:9476:exzh":"He is studying journalism.","example:9476:exzh2":"Journalism plays an important role in society.","example:9476:exzh3":"This school has a journalism major.","example:9476:exzh4":"I want to do work involved in journalism.","example:9476:exzh5":"I'm thinking about what good journalism is."},"9477":{"example:9477:exzh":"He was praised for his fine effort.","example:9477:exzh2":"I gave it my all right to the end.","example:9477:exzh3":"I'm looking forward to your fine effort.","example:9477:exzh4":"She showed a fighting spirit.","example:9477:exzh5":"I wish you a fine effort at this tournament."},"9478":{"example:9478:exzh":"Were your exam scores good?","example:9478:exzh2":"His score was very high.","example:9478:exzh3":"I'm studying to raise my score.","example:9478:exzh4":"I didn't have enough points, so I couldn't take the next exam.","example:9478:exzh5":"I'll aim for a high score on the new exam."},"9479":{"example:9479:exzh":"This building stands on elevated ground.","example:9479:exzh2":"Please set the furniture firmly in place.","example:9479:exzh3":"I intend to settle down and get to work on my research.","example:9479:exzh4":"This sculpture is set in a special place.","example:9479:exzh5":"The young sales manager was appointed as the new company president."},"9480":{"example:9480:exzh":"There's a meeting in the office.","example:9480:exzh2":"The office is very quiet.","example:9480:exzh3":"It's important to manage the information within the office.","example:9480:exzh4":"Please follow the rules in the office.","example:9480:exzh5":"The atmosphere in the office is very nice."},"9482":{"example:9482:exzh":"This issue should be resolved through arbitration.","example:9482:exzh2":"Arbitration is carried out based on the agreement of both parties.","example:9482:exzh3":"He has a lot of experience as an arbitrator.","example:9482:exzh4":"By choosing arbitration, we avoided a lawsuit.","example:9482:exzh5":"Arbitration proceedings finish relatively quickly."},"9483":{"example:9483:exzh":"I feel like there's more mucus in my throat now.","example:9483:exzh2":"Mucus is part of the body's defense system.","example:9483:exzh3":"When you catch a cold, mucus increases.","example:9483:exzh4":"A runny nose is a natural thing.","example:9483:exzh5":"He has a disease that causes mucus discharge."},"9484":{"example:9484:exzh":"I attached a file to the email.","example:9484:exzh2":"Please check the attached documents.","example:9484:exzh3":"This document requires a signature and an attachment.","example:9484:exzh4":"Please check the format of the attached file.","example:9484:exzh5":"He read the attached information carefully."},"9485":{"example:9485:exzh":"He made a skeleton model.","example:9485:exzh2":"A skeleton shows the structure of the human body.","example:9485:exzh3":"I saw a skeleton at the museum.","example:9485:exzh4":"Research on skeletons is useful for medicine.","example:9485:exzh5":"She is reading a book about skeletons."},"9486":{"example:9486:exzh":"The purpose of this plan is unclear.","example:9486:exzh2":"His explanation has many unclear parts.","example:9486:exzh3":"The cause of the problem remains unclear.","example:9486:exzh4":"You should avoid vague expressions.","example:9486:exzh5":"That record contains unclear information."},"9487":{"example:9487:exzh":"He should be more careful with his words.","example:9487:exzh2":"Being careful in your actions is important.","example:9487:exzh3":"Being careful earns trust.","example:9487:exzh4":"A cautious attitude is needed.","example:9487:exzh5":"Being careful raises how you're valued at work."},"9489":{"example:9489:exzh":"There's a cat, and it's cute.","example:9489:exzh2":"I have a friend, and we play together.","example:9489:exzh3":"There are many people here, and it's lively.","example:9489:exzh4":"There's a dog at home, and it's very energetic.","example:9489:exzh5":"There's a teacher at school, and they teach us.","grammar:9489:ex:trans":"There's a cat, and it's cute.","grammar:9489:ex:structure":"猫が＋〔いて〕、かわいいです。「いる」＝ (animals/people) exist; 「いて」 is the te-form linking clauses (showing cause).","grammar:9489:ex:explain":"「いる」 is used for living things and 「ある」 for non-living things — the basic division of labor between Japanese existential verbs. Here 「いて」 is the te-form of 「いる」, joining two clauses with a slight sense of cause: because there's a cat there, it feels cute. The entity that exists is marked with 「が」, the fixed particle for existential sentences; unless you're making a contrast, it doesn't become 「は」.","grammar:9489:ex:words:0:zh":"cat","grammar:9489:ex:words:0:note":"ねこ","grammar:9489:ex:words:0:pos":"noun","grammar:9489:ex:words:1:zh":"(nominative)","grammar:9489:ex:words:1:pos":"particle","grammar:9489:ex:words:2:zh":"there is (and)","grammar:9489:ex:words:2:note":"te-form","grammar:9489:ex:words:2:pos":"verb","grammar:9489:ex:words:3:zh":"cute","grammar:9489:ex:words:3:pos":"adjective","grammar:9489:ex:words:4:zh":"(polite form)","grammar:9489:ex:words:4:pos":"copula","grammar:9489:ex:points:0":"いる: (for living things) to exist, to be","grammar:9489:ex:points:1":"〜がいて: there is … and … (いて＝ the te-form of いる)","grammar:9489:ex2:trans":"I have friends, and we play together.","grammar:9489:ex2:structure":"友達が＋〔いて〕、一緒に＋遊びます。「いて」 is the te-form linking clauses.","grammar:9489:ex2:words:0:zh":"friend","grammar:9489:ex2:words:0:note":"ともだち","grammar:9489:ex2:words:0:pos":"noun","grammar:9489:ex2:words:1:zh":"(nominative)","grammar:9489:ex2:words:1:pos":"particle","grammar:9489:ex2:words:2:zh":"there is (and)","grammar:9489:ex2:words:2:note":"te-form","grammar:9489:ex2:words:2:pos":"verb","grammar:9489:ex2:words:3:zh":"together","grammar:9489:ex2:words:3:note":"いっしょに","grammar:9489:ex2:words:3:pos":"adverb","grammar:9489:ex2:words:4:zh":"hang out","grammar:9489:ex2:words:4:note":"あそびます","grammar:9489:ex2:words:4:pos":"verb","grammar:9489:ex2:points:0":"〜がいて: there is … (a person) and …","grammar:9489:ex2:points:1":"「一緒に遊ぶ」: to play together, to hang out together","grammar:9489:ex3:trans":"There are lots of people here, so it's lively.","grammar:9489:ex3:structure":"ここ＋には＋〔多くの人〕＋が＋〔いて〕、賑やかです。「いて」 is the te-form linking clauses (showing cause).","grammar:9489:ex3:words:0:zh":"here","grammar:9489:ex3:words:0:pos":"pronoun","grammar:9489:ex3:words:1:zh":"(location of existence＋emphasis)","grammar:9489:ex3:words:1:pos":"particle","grammar:9489:ex3:words:2:zh":"a lot","grammar:9489:ex3:words:2:note":"おおく","grammar:9489:ex3:words:2:pos":"noun","grammar:9489:ex3:words:3:zh":"'s","grammar:9489:ex3:words:3:pos":"particle","grammar:9489:ex3:words:4:zh":"person","grammar:9489:ex3:words:4:note":"ひと","grammar:9489:ex3:words:4:pos":"noun","grammar:9489:ex3:words:5:zh":"(nominative)","grammar:9489:ex3:words:5:pos":"particle","grammar:9489:ex3:words:6:zh":"there is (and)","grammar:9489:ex3:words:6:note":"te-form","grammar:9489:ex3:words:6:pos":"verb","grammar:9489:ex3:words:7:zh":"busy, lively","grammar:9489:ex3:words:7:note":"にぎやか","grammar:9489:ex3:words:7:pos":"na-adjective","grammar:9489:ex3:words:8:zh":"(polite form)","grammar:9489:ex3:words:8:pos":"copula","grammar:9489:ex3:points:0":"〜がいて: there is … (a person) and …","grammar:9489:ex3:points:1":"賑やか: lively","grammar:9489:ex4:trans":"There's a dog at home, and it's very lively.","grammar:9489:ex4:structure":"家＋には、犬が＋〔いて〕、とても＋元気です。「いて」 is the te-form linking clauses.","grammar:9489:ex4:words:0:zh":"house","grammar:9489:ex4:words:0:note":"いえ","grammar:9489:ex4:words:0:pos":"noun","grammar:9489:ex4:words:1:zh":"(location of existence＋emphasis)","grammar:9489:ex4:words:1:pos":"particle","grammar:9489:ex4:words:2:zh":"dog","grammar:9489:ex4:words:2:note":"いぬ","grammar:9489:ex4:words:2:pos":"noun","grammar:9489:ex4:words:3:zh":"(nominative)","grammar:9489:ex4:words:3:pos":"particle","grammar:9489:ex4:words:4:zh":"there is (and)","grammar:9489:ex4:words:4:note":"te-form","grammar:9489:ex4:words:4:pos":"verb","grammar:9489:ex4:words:5:zh":"extremely","grammar:9489:ex4:words:5:pos":"adverb","grammar:9489:ex4:words:6:zh":"lively","grammar:9489:ex4:words:6:note":"げんき","grammar:9489:ex4:words:6:pos":"na-adjective","grammar:9489:ex4:words:7:zh":"(polite form)","grammar:9489:ex4:words:7:pos":"copula","grammar:9489:ex4:points:0":"〜がいて: there is … (an animal) and …","grammar:9489:ex4:points:1":"元気: lively, full of energy","grammar:9489:ex5:trans":"There are teachers at school who teach us.","grammar:9489:ex5:structure":"学校＋には、先生が＋〔いて〕、教えてくれます。「〜てくれる」＝ (someone else) does something for me.","grammar:9489:ex5:words:0:zh":"school","grammar:9489:ex5:words:0:note":"がっこう","grammar:9489:ex5:words:0:pos":"noun","grammar:9489:ex5:words:1:zh":"(location of existence＋emphasis)","grammar:9489:ex5:words:1:pos":"particle","grammar:9489:ex5:words:2:zh":"teacher","grammar:9489:ex5:words:2:note":"せんせい","grammar:9489:ex5:words:2:pos":"noun","grammar:9489:ex5:words:3:zh":"(nominative)","grammar:9489:ex5:words:3:pos":"particle","grammar:9489:ex5:words:4:zh":"there is (and)","grammar:9489:ex5:words:4:note":"te-form","grammar:9489:ex5:words:4:pos":"verb","grammar:9489:ex5:words:5:zh":"teach (for us)","grammar:9489:ex5:words:5:note":"〜てくれる","grammar:9489:ex5:words:5:pos":"verb","grammar:9489:ex5:points:0":"〜がいて: there is … (a person) and …","grammar:9489:ex5:points:1":"〜てくれる: (someone else) does … for me/us (教えてくれる＝ teaches us)","exam:9489:zh":"I found a cat up in the tree.","exam:9489:why":"A cat is a living creature, so 「いる」 is used to say it's somewhere. 「ある」 is used for the existence of inanimate things like objects."},"9490":{"example:9490:exzh":"I've seen a shark in the sea before.","example:9490:exzh2":"Sharks are frightening fish.","example:9490:exzh3":"The shark is swimming in the sea.","example:9490:exzh4":"Shark meat is very delicious.","example:9490:exzh5":"I like movies about sharks."},"9491":{"example:9491:exzh":"I go to the sauna every week.","example:9491:exzh2":"I relax in the sauna.","example:9491:exzh3":"I went to the sauna with a friend.","example:9491:exzh4":"Saunas are good for your health.","example:9491:exzh5":"I enjoyed the sauna."},"9492":{"example:9492:exzh":"The view from this place is wonderful.","example:9492:exzh2":"I live in a place with a good view.","example:9492:exzh3":"The view of the mountains was beautiful.","example:9492:exzh4":"I went hiking to enjoy the view.","example:9492:exzh5":"The view here is bad."},"9493":{"example:9493:exzh":"This company has many colonies.","example:9493:exzh2":"This district is an old colony.","example:9493:exzh3":"Managing a colony is very difficult.","example:9493:exzh4":"He established a new colony.","example:9493:exzh5":"The colony's development is highly anticipated."},"9494":{"example:9494:exzh":"There is a large altar in front of the shrine.","example:9494:exzh2":"I prayed at the altar.","example:9494:exzh3":"She placed flowers on the altar.","example:9494:exzh4":"I stay quiet in front of the altar.","example:9494:exzh5":"The altar is an important place."},"9495":{"example:9495:exzh":"Bark is the outermost part of a tree.","example:9495:exzh2":"Bark is hard.","example:9495:exzh3":"Bark is sometimes used to make medicine.","example:9495:exzh4":"Animals sometimes eat bark.","example:9495:exzh5":"The color of bark differs depending on the species of tree."},"9498":{"example:9498:exzh":"He says he wants to go back to his hometown.","example:9498:exzh2":"The festival in the hometown is very lively.","example:9498:exzh3":"I have friends in my hometown.","example:9498:exzh4":"This village is rich in nature.","example:9498:exzh5":"I'm studying the history of my hometown."}};